import React, { useEffect, useRef } from 'react';
import './NiftyChart.css';

const NiftyChart = () => {
  const containerRef = useRef();

  useEffect(() => {
    const current = containerRef.current;
    if (!current) return;

    // Clear any previous content
    current.innerHTML = '';

    // Use TradingView Mini Chart for simpler reliable widget
    const widgetHTML = `
      <div class="tradingview-widget-container">
        <div class="tradingview-widget-container__widget"></div>
        <div class="tradingview-widget-copyright">
          <a href="https://www.tradingview.com/" rel="noopener" target="_blank">
            <span class="blue-text">Track all markets on TradingView</span>
          </a>
        </div>
        <script type="text/javascript" src="https://s3.tradingview.com/external-embedding/embed-widget-mini-symbol-overview.js"></script>
        <script type="application/json">
        {
          "symbol": "NSE:NIFTY",
          "width": "100%",
          "height": "350",
          "locale": "en",
          "dateRange": "1M",
          "colorTheme": "light",
          "trendLineColor": "#14C4B5",
          "underLineColor": "rgba(20, 196, 181, 0.3)",
          "underLineBottomColor": "rgba(20, 196, 181, 0)",
          "isTransparent": false,
          "autosize": true
        }
        </script>
      </div>
    `;

    current.innerHTML = widgetHTML;

    return () => {
      if (current) {
        current.innerHTML = '';
      }
    };
  }, []);

  return (
    <div className="chart-widget-block">
      <h3 className="chart-title">India Market: NIFTY 50</h3>
      <div ref={containerRef} className="chart-embed"></div>
    </div>
  );
};

export default NiftyChart;
